  bool _changePWLock = false;
  Future<(bool, FlushBarType, String)> _attemptChangePW() async {
    final String pw = passwordCurrentController.text;
    final String pwNew = passwordController.text;
    final String pwNewRepeat = passwordRepeatController.text;

    final verified = await ref
        .read(storageCryptoHandlerProvider)
        .verifyPassphrase(pw);

    if (verified) {
      final missing = passwordMissing(pwNew);
      if (missing != null) return (false, FlushBarType.warning, missing);
      if (pwNew != pwNewRepeat) {
        await Future<void>.delayed(const Duration(seconds: 1));

        return (false, FlushBarType.warning, l10n.passwordNewMismatch);
      } else {
        final success = await ref
            .read(storageCryptoHandlerProvider)
            .changePassphrase(pw, pwNew);

        if (success) {
          await Future<void>.delayed(const Duration(seconds: 1));

          return (true, FlushBarType.success, l10n.passwordChanged);
        } else {
          await Future<void>.delayed(const Duration(seconds: 1));

          return (false, FlushBarType.warning, l10n.passwordChangeFailed);
        }
      }
    } else {
      await Future<void>.delayed(const Duration(seconds: 1));

      return (false, FlushBarType.warning, l10n.passwordNotCurrent);
    }
  }

